// -----------------------------------------------------------------------------
//	cz80_inst / cr800_inst instruction regression test
//	Runs the cpu_test stub (cpu_test\stub.bin) with the vectors generated by
//	cpu_test\make_rtl_vectors.py and compares the state block with the Z80
//	model (kosarev/z80) results used by cpu_test.rom.
//	+define+R800 selects cr800_inst.
// -----------------------------------------------------------------------------

`timescale 1ps/1ps

module tb;
	localparam	clk_base	= 1_000_000_000 / 42_955;	//	ps (42.954545MHz)
	localparam	OUTB		= 16'hE040;
	localparam	WIN_ADDR	= 16'hD000;
	localparam	O_PATH		= 24;
	localparam	O_WIN		= 32;
	localparam	RESTORE		= 16'hBF00;
	localparam	INS_ADDR	= 16'hC300;
	localparam	TIMEOUT		= 2_000_000;

	reg				clk = 1'b0;
	reg				reset_n = 1'b0;
	reg		[3:0]	state_count = 4'd0;
	wire	[15:0]	bus_address;
	wire	[7:0]	bus_wdata;
	wire			bus_valid;
	wire			bus_write;
	wire			bus_io;
	reg		[7:0]	bus_rdata = 8'hFF;
	reg				bus_rdata_en = 1'b0;
	reg				bus_ready = 1'b0;
	reg		[7:0]	mem [0:65535];
	reg		[7:0]	base [0:65535];
	reg		[7:0]	expected [0:63];
	reg		[3:0]	psg_latch = 4'd0;
	reg		[7:0]	psg_r0 = 8'h00;
	reg		[8*64-1:0]	names [0:4095];

	integer			fv;
	integer			fn;
	integer			rc;
	integer			tid;
	integer			vid;
	integer			npatch;
	integer			fmask;
	integer			exp_wz;
	integer			ins_len;
	integer			got_wz;
	reg				wz_armed = 1'b0;
	reg				wz_sample = 1'b0;
	integer			i;
	integer			a;
	integer			d;
	integer			errors = 0;
	integer			vectors = 0;
	integer			failed_tests = 0;
	integer			last_failed_tid = -1;
	integer			idle_count = 0;
	reg				finished = 1'b0;
	reg		[7:0]	tag;
	reg		[7:0]	got;
	reg		[7:0]	exp_v;
	reg		[8*64-1:0]	line;

	always #(clk_base/2) clk = ~clk;

	always @( posedge clk ) begin
		if( !reset_n ) begin
			state_count <= 4'd0;
		end
		else if( state_count == 4'd11 ) begin
			state_count <= 4'd0;
		end
		else begin
			state_count <= state_count + 4'd1;
		end
	end

`ifdef R800
	cr800_inst u_cpu (
		.reset_n			( reset_n		),
		.clk				( clk			),
		.state_count		( state_count	),
		.int_n				( 1'b1			),
		.nmi_n				( 1'b1			),
		.wait_n				( 1'b1			),
		.m1_n				(				),
		.merq_n				(				),
		.iorq_n				(				),
		.rd_n				(				),
		.wr_n				(				),
		.slot_d_oe			(				),
		.rfsh_n				(				),
		.run_req			( 1'b1			),
		.run_ack			(				),
		.slot_d				( 8'hFF			),
		.flash_cs			( 1'b0			),
		.rom0_cs			( 1'b0			),
		.rom0_address		( 19'd0			),
		.slot12_cs			( 1'b0			),
		.ssram_access		( 1'b0			),
		.bus_io				( bus_io		),
		.bus_write			( bus_write		),
		.bus_valid			( bus_valid		),
		.bus_ready			( bus_ready		),
		.bus_address		( bus_address	),
		.bus_wdata			( bus_wdata		),
		.bus_rdata			( bus_rdata		),
		.bus_rdata_en		( bus_rdata_en	),
		.performance_start	( 1'b0			),
		.performance_stop	( 1'b0			),
		.performance_signal	(				),
		.pc					(				),
		.debug_sp			(				),
		.int_ack			(				)
	);
`else
	cz80_inst u_cpu (
		.reset_n		( reset_n		),
		.clk			( clk			),
		.state_count	( state_count	),
		.int_n			( 1'b1			),
		.nmi_n			( 1'b1			),
		.wait_n			( 1'b1			),
		.m1_n			(				),
		.merq_n			(				),
		.iorq_n			(				),
		.rd_n			(				),
		.wr_n			(				),
		.slot_d_oe		(				),
		.rfsh_n			(				),
		.run_req		( 1'b1			),
		.run_ack		(				),
		.slot_d			( 8'hFF			),
		.bus_io			( bus_io		),
		.bus_write		( bus_write		),
		.bus_valid		( bus_valid		),
		.bus_ready		( bus_ready		),
		.bus_address	( bus_address	),
		.bus_wdata		( bus_wdata		),
		.bus_rdata		( bus_rdata		),
		.bus_rdata_en	( bus_rdata_en	),
		.pc				(				),
		.int_ack		(				)
	);
`endif

	//	Compare the result of the current vector and load the next one.
	task next_vector();
		if( vectors > 0 && exp_wz >= 0 ) begin
			if( got_wz !== exp_wz ) begin
				$display( "NG: %0s vec=%0d WZ expected=%04h got=%04h (in: F=%02h A=%02h B=%02h C=%02h)",
					names[tid], vid, exp_wz, got_wz, mem[16'hE000], mem[16'hE001], mem[16'hE003], mem[16'hE002] );
				errors = errors + 1;
				if( last_failed_tid != tid ) begin
					failed_tests = failed_tests + 1;
					last_failed_tid = tid;
				end
			end
		end
		if( vectors > 0 ) begin
			for( i = 0; i < 64; i = i + 1 ) begin
				if( i <= O_PATH || i >= O_WIN ) begin
					got = ( i >= O_WIN ) ? mem[WIN_ADDR + i - O_WIN] : mem[OUTB + i];
					exp_v = expected[i];
					if( i == 0 ) begin
						got = got & fmask;
						exp_v = exp_v & fmask;
					end
					if( got !== exp_v ) begin
						$display( "NG: %0s vec=%0d off=%0d expected=%02h got=%02h (in: F=%02h A=%02h B=%02h C=%02h)",
							names[tid], vid, i, exp_v, got, mem[16'hE000], mem[16'hE001], mem[16'hE003], mem[16'hE002] );
						errors = errors + 1;
						if( last_failed_tid != tid ) begin
							failed_tests = failed_tests + 1;
							last_failed_tid = tid;
						end
					end
				end
			end
		end
		rc = $fscanf( fv, " %c %d %d %d %d %d %d", tag, tid, vid, npatch, fmask, exp_wz, ins_len );
		if( rc != 7 || tag != "V" ) begin
			finished = 1'b1;
		end
		else begin
			for( a = RESTORE; a < 65536; a = a + 1 ) begin
				mem[a] = base[a];
			end
			for( i = 0; i < npatch; i = i + 1 ) begin
				rc = $fscanf( fv, " %h %h", a, d );
				mem[a] = d;
			end
			for( i = 0; i < 64; i = i + 1 ) begin
				rc = $fscanf( fv, " %h", d );
				expected[i] = d;
			end
			vectors = vectors + 1;
			got_wz = -1;
		end
	endtask

`ifndef R800
	//	MEMPTR right after the instruction under test: cz80 updates WZ at T2 of
	//	the next M1, which is the first M1 outside the instruction bytes.
	always @( posedge clk ) begin
		if( wz_sample ) begin
			got_wz		<= u_cpu.u_cz80.ff_wz;
			wz_sample	<= 1'b0;
		end
		if( u_cpu.u_cz80.clken && u_cpu.u_cz80.wz_update ) begin
			if( u_cpu.u_cz80.pc == INS_ADDR && !wz_armed ) begin
				wz_armed <= 1'b1;
			end
			else if( wz_armed && ( u_cpu.u_cz80.pc < INS_ADDR || u_cpu.u_cz80.pc >= INS_ADDR + ins_len ) ) begin
				wz_armed	<= 1'b0;
				wz_sample	<= 1'b1;
			end
		end
	end
`endif

	//	Memory / I/O model (PSG register 0 is used as a read/write I/O register)
	always @( posedge clk ) begin
		bus_ready		<= 1'b0;
		bus_rdata_en	<= 1'b0;
		idle_count		<= idle_count + 1;
		if( reset_n && bus_valid && !bus_ready && !bus_rdata_en ) begin
			if( bus_write ) begin
				if( bus_io ) begin
					case( bus_address[7:0] )
					8'hA0:	psg_latch <= bus_wdata[3:0];
					8'hA1:	if( psg_latch == 4'd0 ) psg_r0 <= bus_wdata;
					8'hFE:
						begin
							next_vector();
							idle_count <= 0;
						end
					default: begin end
					endcase
				end
				else begin
					mem[bus_address] = bus_wdata;
				end
				bus_ready <= 1'b1;
			end
			else begin
				if( bus_io ) begin
					bus_rdata <= ( bus_address[7:0] == 8'hA2 && psg_latch == 4'd0 ) ? psg_r0 : 8'hFF;
				end
				else begin
					bus_rdata <= mem[bus_address];
				end
				bus_rdata_en <= 1'b1;
			end
		end
	end

	initial begin
		$readmemh( "base.hex", base );
		for( a = 0; a < 65536; a = a + 1 ) begin
			mem[a] = base[a];
		end
		//	reset vector: JP BF20h (restored to the RST 00h entry once the loop is reached)
		mem[0] = 8'hC3;
		mem[1] = 8'h20;
		mem[2] = 8'hBF;
		fn = $fopen( "names.txt", "r" );
		i = 0;
		while( !$feof( fn ) && i < 4096 ) begin
			rc = $fgets( line, fn );
			if( rc > 0 ) begin
				while( line[7:0] == 8'h0A || line[7:0] == 8'h0D ) begin
					line = line >> 8;
				end
				names[i] = line;
				i = i + 1;
			end
		end
		$fclose( fn );
		fv = $fopen( "vectors.txt", "r" );
		next_vector();

		repeat( 4 ) @( posedge clk );
		reset_n = 1'b1;
		wait( bus_valid && bus_address == 16'hBF21 );
		mem[0] = base[0];
		mem[1] = base[1];
		mem[2] = base[2];

		while( !finished ) begin
			@( posedge clk );
			if( idle_count > TIMEOUT ) begin
				$display( "TIMEOUT: %0s vec=%0d", names[tid], vid );
				errors = errors + 1;
				finished = 1'b1;
			end
		end
		$display( "RESULT: vectors=%0d errors=%0d failed_tests=%0d", vectors, errors, failed_tests );
		if( errors == 0 ) begin
			$display( "PASS" );
		end
		else begin
			$display( "FAIL" );
		end
		$finish;
	end
endmodule
